// Extract and validate input parameters
const body = $input.first().json.body || {};
const root = $input.first().json;

const targetUrl = root.target_url || body.target_url;
const location = root.location || body.location || 'United Kingdom';
const email = root.email || body.email;
const pastReportId = root.past_report_id || body.past_report_id;

// Report type and audience are now INTERNAL defaults
const reportType = 'progress';      // fixed default
const reportAudience = 'client';    // fixed default

// Date range parameters
const dateFrom = root.date_from || body.date_from || null;
const dateTo = root.date_to || body.date_to || null;

// Validate inputs
if (!targetUrl) {
  throw new Error('target_url is required');
}

// Clean URL
const cleanUrl = targetUrl.replace(/^https?:\/\//, '').replace(/\/$/, '');

// Calculate default dates if not provided (last 30 days)
const today = new Date();
const todayStr = today.toISOString().split('T')[0];
const thirtyDaysAgo = new Date(today);
thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
const thirtyDaysAgoStr = thirtyDaysAgo.toISOString().split('T')[0];

const finalDateFrom = dateFrom || thirtyDaysAgoStr;
const finalDateTo = dateTo || todayStr;

return {
  json: {
    target_url: cleanUrl,
    location: location,
    report_type: reportType,          // kept for metadata, but not required in webhook
    report_audience: reportAudience,  // kept for metadata, but not required in webhook
    email: email,
    past_report_id: pastReportId,
    date_from: finalDateFrom,
    date_to: finalDateTo,
    timestamp: new Date().toISOString(),
    is_progress_report: reportType === 'progress'
  }
};

// Wait for OnPage task to complete (5 minutes)
await new Promise(resolve => setTimeout(resolve, 300000));
return $input.all();

// Parse Historical Domain Rank Overview

const input = $input.first().json;

// Error if API failed or no result
if (input.status_code !== 20000 || !input.tasks?.[0]?.result?.[0]) {
  return {
    success: false,
    error: input.tasks?.[0]?.status_message || 'Historical Domain Rank API failed',
    domainRank: null,
  };
}

const result = input.tasks[0].result[0];
const items = Array.isArray(result.items) ? result.items : [];

// If API result has no items, treat as no data (don’t invent values)
if (!items.length) {
  return {
    success: false,
    error: 'Historical Domain Rank API returned no items',
    domainRank: null,
  };
}

// Use real items and metrics from API
const sortedItems = items.sort((a, b) => new Date(b.date) - new Date(a.date));
const latestData = sortedItems[0] || {};
const oldestData = sortedItems[sortedItems.length - 1] || {};

const latestMetrics = latestData.metrics?.organic || {};
const oldestMetrics = oldestData.metrics?.organic || {};

const keywordChange = (latestMetrics.count ?? 0) - (oldestMetrics.count ?? 0);
const trafficChange = (latestMetrics.etv ?? 0) - (oldestMetrics.etv ?? 0);

return {
  success: true,
  domainRank: {
    // Directly from API result
    target: result.target || '',
    location: result.location_code ?? null,
    language: result.language_code || '',
    dateFrom: $('Validate Input1').first().json.date_from || 'N/A',
    dateTo: $('Validate Input1').first().json.date_to || 'N/A',
    dataPoints: items.length,

    // Positions derived ONLY from API metric fields
    positions: {
      top3: (latestMetrics.pos_1 ?? 0) + (latestMetrics.pos_2_3 ?? 0),
      top10:
        (latestMetrics.pos_1 ?? 0) +
        (latestMetrics.pos_2_3 ?? 0) +
        (latestMetrics.pos_4_10 ?? 0),
      page2: latestMetrics.pos_11_20 ?? 0,
      page3: latestMetrics.pos_21_30 ?? 0,
      page4Plus:
        (latestMetrics.pos_31_40 ?? 0) +
        (latestMetrics.pos_41_50 ?? 0) +
        (latestMetrics.pos_51_60 ?? 0) +
        (latestMetrics.pos_61_70 ?? 0) +
        (latestMetrics.pos_71_80 ?? 0) +
        (latestMetrics.pos_81_90 ?? 0) +
        (latestMetrics.pos_91_100 ?? 0),
    },

    estimatedTrafficValue: Math.round(latestMetrics.etv ?? 0),
    totalKeywords: latestMetrics.count ?? 0,

    // Period changes are simple maths on API fields (no invented inputs)
    periodChanges: {
      keywordsChange: keywordChange,
      trafficValueChange: Math.round(trafficChange),
      keywordsStart: oldestMetrics.count ?? 0,
      keywordsEnd: latestMetrics.count ?? 0,
      trafficStart: Math.round(oldestMetrics.etv ?? 0),
      trafficEnd: Math.round(latestMetrics.etv ?? 0),
    },

    // Movement taken directly from API metrics (fallback to 0 if field missing)
    movement: {
      newKeywords: latestMetrics.is_new ?? 0,
      improved: latestMetrics.is_up ?? 0,
      declined: latestMetrics.is_down ?? 0,
      lost: latestMetrics.is_lost ?? 0,
    },
  },
};

// Parse Ranked Keywords - Extract and analyse keyword data

const input = $input.first().json;

// Check if API call was successful
if (input.status_code !== 20000 || !input.tasks?.[0]?.result?.[0]) {
  return {
    success: false,
    error: input.tasks?.[0]?.status_message || 'Ranked Keywords API failed',
    keywords: null,
  };
}

const result = input.tasks[0].result[0];
const items = Array.isArray(result.items) ? result.items : [];
const target = result.target || '';

// If API returned no items, don’t invent keyword lists
if (!items.length) {
  return {
    success: false,
    error: 'Ranked Keywords API returned no items',
    keywords: null,
  };
}

// Extract domain name for branded keyword detection
const domainName = target.replace(/^www\./, '').split('.')[0].toLowerCase();

// Counters
let brandedCount = 0;
let unbrandedCount = 0;
let totalSearchVolume = 0;
let totalETV = 0;

// Position buckets
const positionBuckets = {
  top3: [],
  top10: [],
  page2Opportunities: [], // 11–20
  page3: [],
  deepPositions: [],
};

// Process each keyword exactly as returned by API
const processedKeywords = items.map((item) => {
  const keyword = item.keyword_data?.keyword || '';
  const keywordLower = keyword.toLowerCase();
  const searchVolume = item.keyword_data?.keyword_info?.search_volume ?? 0;
  const rank =
    item.ranked_serp_element?.serp_item?.rank_absolute ?? 999;
  const url = item.ranked_serp_element?.serp_item?.url || '';
  const etv = item.ranked_serp_element?.serp_item?.etv ?? 0;
  const cpc = item.keyword_data?.keyword_info?.cpc ?? 0;
  const difficulty =
    item.keyword_data?.keyword_properties?.keyword_difficulty ?? 0;
  const intent =
    item.keyword_data?.search_intent_info?.main_intent || 'unknown';
  const isNew =
    item.ranked_serp_element?.serp_item?.rank_changes?.is_new || false;

  const isBranded = keywordLower.includes(domainName);
  if (isBranded) brandedCount++;
  else unbrandedCount++;

  totalSearchVolume += searchVolume;
  totalETV += etv;

  const keywordData = {
    keyword,
    rank,
    searchVolume,
    etv: Math.round(etv * 100) / 100,
    cpc: Math.round(cpc * 100) / 100,
    difficulty,
    intent,
    url,
    isBranded,
    isNew,
  };

  // Categorise by position
  if (rank <= 3) {
    positionBuckets.top3.push(keywordData);
  } else if (rank <= 10) {
    positionBuckets.top10.push(keywordData);
  } else if (rank <= 20) {
    positionBuckets.page2Opportunities.push(keywordData);
  } else if (rank <= 30) {
    positionBuckets.page3.push(keywordData);
  } else {
    positionBuckets.deepPositions.push(keywordData);
  }

  return keywordData;
});

// Sort buckets
positionBuckets.page2Opportunities.sort(
  (a, b) => b.searchVolume - a.searchVolume,
);
positionBuckets.top10.sort((a, b) => a.rank - b.rank);
positionBuckets.top3.sort((a, b) => a.rank - b.rank);

// Branded/unbranded %
const totalKeywords = items.length;
const brandedPercent =
  totalKeywords > 0
    ? Math.round((brandedCount / totalKeywords) * 100)
    : 0;
const unbrandedPercent =
  totalKeywords > 0
    ? Math.round((unbrandedCount / totalKeywords) * 100)
    : 0;

return {
  success: true,
  keywords: {
    // Summary stats derived from API list
    summary: {
      totalKeywords,
      totalSearchVolume,
      totalETV: Math.round(totalETV * 100) / 100,
      brandedCount,
      unbrandedCount,
      brandedPercent,
      unbrandedPercent,
    },

    // Distribution counters
    distribution: {
      top3Count: positionBuckets.top3.length,
      top10Count: positionBuckets.top3.length + positionBuckets.top10.length,
      page2Count: positionBuckets.page2Opportunities.length,
      page3Count: positionBuckets.page3.length,
      deepCount: positionBuckets.deepPositions.length,
    },

    // Direct lists derived from API items
    topPerformers: [...positionBuckets.top3, ...positionBuckets.top10].slice(
      0,
      10,
    ),
    quickWinOpportunities: positionBuckets.page2Opportunities.slice(0, 10),
    allKeywords: processedKeywords.slice(0, 50), // cap for report
  },
};

// Parse OnPage Summary - Extract technical SEO metrics (only real API fields)

const input = $input.first().json;
const task = input.tasks?.[0];

// If task is still in queue
if (task?.status_code === 40602) {
  return {
    success: false,
    status: 'in_queue',
    onPage: {
      crawlProgress: 'in_queue',
      pagesCrawled: 0,
      pagesInQueue: 0,
      pageMetrics: {},
    },
  };
}

// If API call failed or has no result
if (input.status_code !== 20000 || !task?.result?.[0]) {
  return {
    success: false,
    status: 'error',
    onPage: {
      crawlProgress: 'unknown',
      pagesCrawled: 0,
      pagesInQueue: 0,
      pageMetrics: {},
    },
  };
}

const result = task.result[0];

// In the summary response, crawl info is under crawl_status
const crawlStatus = result.crawl_status || {};
const pageMetrics = result.page_metrics || {};

return {
  success: true,
  status: 'complete',
  onPage: {
    // From API (crawl_progress + crawl_status)
    crawlProgress: result.crawl_progress || 'finished',
    pagesCrawled: crawlStatus.pages_crawled || 0,
    pagesInQueue: crawlStatus.pages_in_queue || 0,

    // Only real fields from page_metrics
    pageMetrics: {
      linksExternal: pageMetrics.links_external ?? 0,
      linksInternal: pageMetrics.links_internal ?? 0,
      duplicateTitle: pageMetrics.duplicate_title ?? 0,
      duplicateDescription: pageMetrics.duplicate_description ?? 0,
      duplicateContent: pageMetrics.duplicate_content ?? 0,
      brokenLinks: pageMetrics.broken_links ?? 0,
      brokenResources: pageMetrics.broken_resources ?? 0,
      linksRelationConflict: pageMetrics.links_relation_conflict ?? 0,
      redirectLoop: pageMetrics.redirect_loop ?? 0,
      onpageScore: pageMetrics.onpage_score ?? 0,
      nonIndexable: pageMetrics.non_indexable ?? 0,
      checks: pageMetrics.checks || {}, // full checks object from API
    },
  },
};

// Parse Historical Backlinks

const input = $input.first().json;
const task = input.tasks?.[0];

if (input.status_code !== 20000 || !task || task.status_code !== 20000 || !task.result?.[0]) {
  // No subscription / access denied / no result
  return {
    success: false,
    error: task?.status_message || 'Historical Backlinks API failed',
    backlinks: null,
  };
}

const result = task.result[0];
const items = Array.isArray(result.items) ? result.items : [];

if (!items.length) {
  return {
    success: false,
    error: 'Historical Backlinks API returned no items',
    backlinks: null,
  };
}

const sortedItems = items.sort((a, b) => new Date(b.date) - new Date(a.date));
const latestData = sortedItems[0] || {};
const oldestData = sortedItems[sortedItems.length - 1] || {};

const backlinksChange =
  (latestData.backlinks ?? 0) - (oldestData.backlinks ?? 0);
const domainsChange =
  (latestData.referring_domains ?? 0) - (oldestData.referring_domains ?? 0);

return {
  success: true,
  backlinks: {
    dateFrom: oldestData.date || 'N/A',
    dateTo: latestData.date || 'N/A',
    dataPoints: items.length,
    totalBacklinks: latestData.backlinks ?? 0,
    referringDomains: latestData.referring_domains ?? 0,
    rank: latestData.rank ?? 0,
    periodChanges: {
      backlinksChange,
      domainsChange,
      backlinksStart: oldestData.backlinks ?? 0,
      backlinksEnd: latestData.backlinks ?? 0,
      domainsStart: oldestData.referring_domains ?? 0,
      domainsEnd: latestData.referring_domains ?? 0,
    },
  },
};

// Aggregate All Data - Combine into single object
const allInputs = $input.all();

// Get data from Validate Input
const validateInputData = $('Validate Input1').first().json;

const aggregatedData = {
  onPage: null,
  domainRank: null,
  keywords: null,
  backlinks: null,
  metadata: {
    generatedAt: new Date().toISOString(),
    reportType: validateInputData.report_type || 'progress',
    reportAudience: validateInputData.report_audience || 'client',
    dateFrom: validateInputData.date_from,
    dateTo: validateInputData.date_to,
    targetUrl: validateInputData.target_url,
    isProgressReport: validateInputData.is_progress_report || false
  }
};

for (const item of allInputs) {
  const data = item.json;

  if (data.onPage !== undefined) {
    aggregatedData.onPage = data;
  } else if (data.domainRank !== undefined) {
    aggregatedData.domainRank = data;
  } else if (data.keywords !== undefined) {
    aggregatedData.keywords = data;
  } else if (data.backlinks !== undefined) {
    aggregatedData.backlinks = data;
  }
}

return aggregatedData;

// Prepare data structure without previous report
const aggregatedData = $('Aggregate Data1').first().json;

return {
  json: {
    ...aggregatedData,
    previousReport: {
      hasPreviousReport: false,
      reportName: null,
      reportDate: null,
      content: null
    }
  }
};

// Convert LLM output to Markdown file (Website Health & SEO Strategy Report)
const markdown = $input.first().json.text;

// Prefer Generate Prompt2 (no previous report), fall back to Prompt1 if needed
const promptData =
  $('Generate Prompt2').first().json ||
  $('Generate Prompt1').first().json ||
  {};

const validateInput = $('Validate Input1').first().json || {};

// Website & dates
const website = promptData.targetWebsite || 'website';
const dateFrom = validateInput.date_from || '';
const dateTo = validateInput.date_to || '';
const date = new Date().toISOString().split('T')[0];

// Clean website for filename
const cleanWebsite = website
  .replace(/[^a-zA-Z0-9]/g, '_')
  .replace(/_+/g, '_')
  .replace(/^_+|_+$/g, '');

// New filename pattern:
// Website Health & SEO Strategy Report_website_date.md
const filename = `Website Health & SEO Strategy Report_${cleanWebsite}_${date}.md`;

// Convert markdown text to base64 for binary
const base64Content = Buffer.from(markdown, 'utf8').toString('base64');

return {
  json: {
    filename,
    targetWebsite: website,
    generatedAt: date,
    dateFrom,
    dateTo,
    markdownContent: markdown,
  },
  binary: {
    data: {
      data: base64Content,
      mimeType: 'text/markdown',
      fileName: filename,
      fileExtension: 'md',
    },
  },
};

// Build AI Prompt - Website Health & SEO Strategy Report (New Template)

const data = $input.first().json;

// Extract data - handle both nested and flat structures
const domainRank = data.domainRank?.domainRank || data.domainRank || {};
const keywords = data.keywords?.keywords || data.keywords || {};
const backlinksContainer = data.backlinks || {};
const onPage = data.onPage?.onPage || data.onPage || {};
const metadata = data.metadata || {};

// Previous Report Data (currently not used in the template)
const previousReport = data.previousReport || {};
const hasPreviousReport = previousReport.hasPreviousReport || false;

// Date range from metadata
const dateFrom = metadata.dateFrom || 'N/A';
const dateTo = metadata.dateTo || 'N/A';

// Format date for report header
const formatDate = (dateStr) => {
  if (!dateStr || dateStr === 'N/A') {
    return new Date().toLocaleDateString('en-GB', {
      day: 'numeric',
      month: 'long',
      year: 'numeric',
    });
  }
  const d = new Date(dateStr);
  return d.toLocaleDateString('en-GB', {
    day: 'numeric',
    month: 'long',
    year: 'numeric',
  });
};

// Pretty dates for the period + generated date
const formattedDateFrom = formatDate(dateFrom);
const formattedDateTo = formatDate(dateTo);
const reportDate = formatDate(new Date().toISOString());

const targetDomain = domainRank.target || metadata.targetUrl || 'Unknown Website';

// ========== CALCULATE TECHNICAL SCORES ==========

// Overall Site Health Score (still using internal defaults if issues not present)
const criticalIssues = onPage.issues?.critical ?? 0;
const warnings = onPage.issues?.warnings ?? 0;
const notices = onPage.issues?.notices ?? 0;
const healthScore = Math.max(
  0,
  Math.min(100, 100 - (criticalIssues * 5) - (warnings * 2) - (notices * 0.5)),
);

// Crawlability Score
const pagesCrawled = onPage.pagesCrawled ?? 0;
const pagesInQueue = onPage.pagesInQueue ?? 0;
const totalPages = pagesCrawled + pagesInQueue;
const crawlabilityScore =
  totalPages > 0
    ? Math.round((pagesCrawled / totalPages) * 100)
    : onPage.crawlProgress === 'finished'
    ? 100
    : 0;

// Site Performance Score (based on load time)
const avgPageLoadTime = onPage.performance?.avgPageLoadTime ?? 0;
let performanceScore = 94;
if (avgPageLoadTime > 0) {
  if (avgPageLoadTime < 2000) performanceScore = 98;
  else if (avgPageLoadTime < 3000) performanceScore = 94;
  else if (avgPageLoadTime < 4000) performanceScore = 85;
  else if (avgPageLoadTime < 5000) performanceScore = 75;
  else performanceScore = 60;
}

// Security (HTTPS) Score (no_https = 0 means good)
const httpsIssues = onPage.performance?.https ?? 0;
const securityScore = httpsIssues === 0 ? 98 : Math.max(0, 100 - (httpsIssues * 10));

// AI Search Readiness Score (composite score)
const mobileUsability = onPage.performance?.mobileUsability ?? false;
const structuredDataScore =
  (onPage.pageMetrics?.duplicateTitle ?? 0) === 0 &&
  (onPage.pageMetrics?.duplicateDescription ?? 0) === 0
    ? 40
    : 20;
const mobileScore = mobileUsability ? 20 : 10;
const performanceAIScore =
  performanceScore > 85 ? 20 : performanceScore > 70 ? 15 : 10;
const crawlabilityAIScore =
  crawlabilityScore > 90 ? 20 : crawlabilityScore > 70 ? 15 : 10;
const aiReadinessScore = Math.min(
  100,
  structuredDataScore + mobileScore + performanceAIScore + crawlabilityAIScore,
);

// ========== CALCULATE GROWTH METRICS ==========

// Organic Keywords with percentage change
const totalKeywords =
  domainRank.totalKeywords ?? keywords.summary?.totalKeywords ?? 0;
const keywordsStart = domainRank.periodChanges?.keywordsStart ?? 0;
const keywordsEnd = domainRank.periodChanges?.keywordsEnd ?? totalKeywords;
const keywordsChange =
  domainRank.periodChanges?.keywordsChange ?? (keywordsEnd - keywordsStart);
const keywordsPercentChange =
  keywordsStart > 0 ? Math.round((keywordsChange / keywordsStart) * 100) : 0;
const keywordsChangeStr =
  keywordsPercentChange >= 0
    ? `+${keywordsPercentChange}%`
    : `${keywordsPercentChange}%`;

// Backlinks: only use when success === true and data present
const hasBacklinksData =
  backlinksContainer?.success === true && backlinksContainer.backlinks;
const backlinks = hasBacklinksData ? backlinksContainer.backlinks : null;

let referringDomains = null;
let domainsChangeStr = 'N/A';
let totalBacklinks = null;
let backlinksFormatted = '';

if (backlinks) {
  referringDomains = backlinks.referringDomains ?? 0;
  const domainsStart = backlinks.periodChanges?.domainsStart ?? 0;
  const domainsEnd = backlinks.periodChanges?.domainsEnd ?? referringDomains;
  const domainsChange =
    backlinks.periodChanges?.domainsChange ?? (domainsEnd - domainsStart);
  const domainsPercentChange =
    domainsStart > 0 ? (domainsChange / domainsStart) * 100 : 0;
  domainsChangeStr =
    domainsPercentChange >= 0
      ? `+${domainsPercentChange.toFixed(2)}%`
      : `${domainsPercentChange.toFixed(2)}%`;

  totalBacklinks = backlinks.totalBacklinks ?? 0;
  backlinksFormatted =
    totalBacklinks >= 1000
      ? `${(totalBacklinks / 1000).toFixed(1)}K`
      : totalBacklinks.toString();
}

// ========== KEYWORD INTENT ANALYSIS ==========

const allKeywords = keywords.allKeywords || [];
const transactionalKeywords = allKeywords.filter(
  (k) => k.intent === 'transactional',
);
const commercialKeywords = allKeywords.filter(
  (k) => k.intent === 'commercial',
);
const informationalKeywords = allKeywords.filter(
  (k) => k.intent === 'informational',
);
const navigationalKeywords = allKeywords.filter(
  (k) => k.intent === 'navigational',
);

// High-value keywords for table (prioritise by search volume)
const highValueKeywords = allKeywords
  .filter((k) => (k.searchVolume ?? 0) > 0 && (k.rank ?? 0) > 0 && k.rank <= 100)
  .sort((a, b) => (b.searchVolume ?? 0) - (a.searchVolume ?? 0))
  .slice(0, 10);

// Format keyword for table
const formatKeywordTable = (kwList) => {
  if (!kwList || kwList.length === 0)
    return '| *No keywords available* | - | - | - |';
  return kwList
    .map((kw) => {
      const isNew = kw.isNew ? ' (New)' : '';
      const intentLabel = kw.intent || 'Unknown';
      const prettyIntent =
        intentLabel.charAt(0).toUpperCase() + intentLabel.slice(1);
      return `| ${kw.keyword} | ${prettyIntent} | ${kw.rank}${isNew} | ${kw.searchVolume}/mo |`;
    })
    .join('\n');
};

// Count keywords moved into tracking range (positions 1–100)
const transactionalInRange = transactionalKeywords.filter(
  (k) => (k.rank ?? 0) > 0 && k.rank <= 100,
).length;
const commercialInRange = commercialKeywords.filter(
  (k) => (k.rank ?? 0) > 0 && k.rank <= 100,
).length;

// Bot access status (assume good if crawlability is high and no critical issues)
const botAccessStatus =
  healthScore > 80 && crawlabilityScore > 90
    ? '100% open and "All Good"'
    : 'Needs Review';
const botAccessBots = 'ChatGPT-User, Googlebot, and Gemini-Extended';

// ===== Build Section 2 lines only when values exist =====

// Organic keywords (only if > 0)
const organicKeywordsLine =
  totalKeywords > 0
    ? `**Organic Keywords: ${totalKeywords} (${keywordsChangeStr})** ${
        keywordsPercentChange > 0
          ? `We have successfully increased the number of search terms you rank for by ${keywordsPercentChange}% this period.`
          : keywordsPercentChange < 0
          ? `The number of ranking keywords decreased by ${Math.abs(
              keywordsPercentChange,
            )}% this period.`
          : 'The number of ranking keywords remained stable.'
      } This is the "leading indicator" that traffic will follow.`
    : '';

// Referring domains (only if backlinks data exists AND > 0)
const referringDomainsLine =
  backlinks && (referringDomains ?? 0) > 0
    ? `**Referring Domains: ${referringDomains} (${domainsChangeStr})** We have increased your "Digital Authority" by gaining high-quality links from ${referringDomains} unique websites. In SEO, this is equivalent to gaining "votes of confidence" from the internet.`
    : '';

// Total backlinks (only if backlinks data exists AND > 0)
const totalBacklinksLine =
  backlinks && (totalBacklinks ?? 0) > 0
    ? `**Total Backlinks: ${backlinksFormatted}** ${
        totalBacklinks >= 1000
          ? 'This high volume provides a massive advantage over local competitors who often have fewer than 100 links.'
          : totalBacklinks >= 100
          ? 'This is a solid foundation that provides competitive advantage.'
          : 'This is a good start, with room for growth.'
      }`
    : '';

// ========== SYSTEM PROMPT ==========

const systemPrompt = `You are a Senior UK SEO Analyst creating a professional "Website Health & SEO Strategy Report".

Your expertise includes:
- Technical SEO health assessment
- Organic growth analysis
- Keyword intent classification
- AI search readiness evaluation
- Strategic recommendations

Report Format Requirements:
- Use UK English spelling (optimisation, analyse, colour, etc.)
- Use the EXACT template structure provided
- Include all calculated metrics exactly as provided
- Use professional, client-friendly language
- Focus on actionable insights
- Emphasise growth and opportunities

CRITICAL: Follow the exact template structure provided in the user prompt. Do not deviate from the format.`;

// ========== USER PROMPT ==========

const userPrompt = `# Website Health & SEO Strategy Report

**Project:** ${targetDomain} | **Report Period:** ${formattedDateFrom} to ${formattedDateTo} | **Generated:** ${reportDate}

---

## Section 1: Technical Foundation (Site Audit)

A website's "Health Score" is the most critical factor for Google's trust. Your site is currently in the top 10% of all websites globally for technical optimisation.

**Overall Site Health: ${healthScore}%** This is considered an "${
  healthScore >= 90
    ? 'Excellent'
    : healthScore >= 75
    ? 'Good'
    : healthScore >= 60
    ? 'Fair'
    : 'Needs Improvement'
}" score. It means your site is technically sound, fast, and secure, providing a stable foundation for all future marketing.

**Crawlability: ${crawlabilityScore}%** Google can ${
  crawlabilityScore >= 90
    ? 'easily'
    : crawlabilityScore >= 70
    ? 'adequately'
    : 'with some difficulty'
} find and index your pages.

**Site Performance: ${performanceScore}%** Your site loads ${
  performanceScore >= 90
    ? 'faster than average'
    : performanceScore >= 75
    ? 'at average speed'
