// ===== OnPage (summary) =====
// Shape now: data.onPage = { success, status, onPage: { crawlProgress, pagesCrawled, pagesInQueue, pageMetrics } }

let hasOnPage = false;
if (data.onPage?.success && data.onPage.onPage) {
  const op = data.onPage.onPage;
  const pm = op.pageMetrics || {};

  hasOnPage =
    (op.pagesCrawled || 0) > 0 ||
    (pm.duplicateContent || 0) > 0 ||
    (pm.brokenLinks || 0) > 0 ||
    (pm.brokenResources || 0) > 0 ||
    (pm.linksExternal || 0) > 0 ||
    (pm.linksInternal || 0) > 0 ||
    (pm.onpageScore || 0) > 0;
}

// ===== Domain Rank =====
// Shape: data.domainRank = { success, domainRank: {...} }

let hasDomainRank = false;
if (data.domainRank?.success && data.domainRank.domainRank) {
  const dr = data.domainRank.domainRank;
  hasDomainRank =
    (dr.totalKeywords || 0) > 0 ||
    (dr.estimatedTrafficValue || 0) > 0 ||
    (dr.positions?.top3 || 0) > 0 ||
    (dr.positions?.top10 || 0) > 0 ||
    (dr.positions?.page2 || 0) > 0 ||
    (dr.positions?.page3 || 0) > 0 ||
    (dr.positions?.page4Plus || 0) > 0 ||
    (dr.movement?.newKeywords || 0) > 0 ||
    (dr.movement?.improved || 0) > 0 ||
    !!dr.target;
}

// ===== Keywords =====
// Shape: data.keywords = { success, keywords: {...} }

let hasKeywords = false;
if (data.keywords?.success && data.keywords.keywords) {
  const kw = data.keywords.keywords;
  hasKeywords =
    (kw.summary?.totalKeywords || 0) > 0 ||
    (kw.summary?.totalSearchVolume || 0) > 0 ||
    (kw.summary?.totalETV || 0) > 0 ||
    (kw.distribution?.top3Count || 0) > 0 ||
    (kw.distribution?.top10Count || 0) > 0 ||
    (kw.topPerformers?.length || 0) > 0 ||
    (kw.quickWinOpportunities?.length || 0) > 0 ||
    (kw.allKeywords?.length || 0) > 0;
}

// ===== Backlinks =====
// Shape: data.backlinks = { success, backlinks: {...} } OR null

let hasBacklinks = false;
if (data.backlinks?.success && data.backlinks.backlinks) {
  const bl = data.backlinks.backlinks;
  hasBacklinks =
    (bl.totalBacklinks || 0) > 0 ||
    (bl.referringDomains || 0) > 0 ||
    (bl.rank || 0) > 0 ||
    (bl.periodChanges?.backlinksChange || 0) !== 0 ||
    (bl.periodChanges?.domainsChange || 0) !== 0;
}

// Count valid data sources
const dataCount = [hasOnPage, hasDomainRank, hasKeywords, hasBacklinks].filter(Boolean).length;

// Require at least 2 out of 4 data sources to be valid
const hasValidData = dataCount >= 2;

return {
  hasValidData,
  dataCount,
  totalSources: 4,
  checks: {
    onPage: hasOnPage,
    domainRank: hasDomainRank,
    keywords: hasKeywords,
    backlinks: hasBacklinks,
  },
  aggregatedData: data,
  validationMessage: hasValidData
